["ItemText"] = {
["Item-191733"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "Malygos, my Aspect...\r\n\r\nThe dracthyr remain securely in stasis, and my long vigil watching over them continues. While I am reluctant to trouble you, I fear I must report that the integrity of this creche has been compromised.\r\n\r\nAn insectoid infestation has breached these halls. In my own arrogance, I at first believed this incursion would prove little more than an annoyance of unwanted pests.\r\n\r\nBut now the contamination spreads out of control, and I find myself short of breath as I am overwhelmed by the toxins produced by this invasive species.\r\n\r\nI refuse to abandon the post you assigned to me, but I must request additional aid. It seems my arcane skills are insufficient to counteract this malady.\r\n\r\nYour loyal servant,\r\n\r\nAndesigos",
},
},
},
["Title"] = {
["enUS"] = "Report: Infestation",
},
["Source"] = {
["ID"] = 191733,
["Type"] = "Item",
},
},
["GameObject-252385"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "I am Illysanna, daughter of the resistance commander Kur'talos Ravencrest. You should know by now that my father is dead. I am not the only one who has lost someone. Our great empire, our entire world, is burning before our eyes.\r\n\r\nNothing in this war with the Burning Legion has gone according to plan. Nothing. Every battle we win is followed by two defeats. Every demon we slay is replaced by ten more.\r\n\r\nLike my father, I was once so certain of victory. So overconfident. So foolish. Most resistance fighters still are. They hold tight to their archaic ways, unwilling to accept that we cannot best our enemy through conventional means. We are fighting something alien to this world, something born of nightmare.\r\n\r\nThere is one elf who understands this: Illidan Stormrage. He knows that to defeat the demons, we must adapt. We must embrace extraordinary new tactics. If not, we will die. It is as simple as that.",
},
{
["Page"] = 2,
["Text"] = "Perhaps you consider Illidan an arrogant sorcerer, or even a menace to our way of life. I once did, but my opinions have changed. I am writing to explain why, and to chronicle what I have learned of Illidan. Despite his dangerous reputation, I believe he is our only chance of surviving the days ahead.",
},
},
},
["Title"] = {
["enUS"] = "Torn Page",
},
["Source"] = {
["ID"] = 252385,
["Type"] = "GameObject",
},
},
["Item-140263"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "THE EMERALD ASCENSION\r\n\r\nFear not the time when great Sargeras's shadow eclipses the sun. \r\n\r\nThat is the moment of our ascension. \r\n\r\nDeath will follow, but it is only a doorway. \r\n\r\nStep through, and you will shed your frail skin and take on a form kissed by emerald fire.\r\n\r\nDig the ash from your eyes, and you will find a higher purpose at Sargeras's side.",
},
},
},
["Title"] = {
["enUS"] = "Worn Pamphlet",
},
["Source"] = {
["ID"] = 140263,
["Type"] = "Item",
},
},
["GameObject-252386"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "I first met Illidan in the early stages of the war, back when I considered the Burning Legion a passing threat. The night elf resistance was headquartered at my family's ancestral home, the great fortress of Black Rook Hold. Those days were glorious to behold. Thousands of elves gathered at the stronghold from the far ends of the empire, all sworn to defend our lands against the demons.\r\n\r\nAs the daughter of Commander Ravencrest, I enjoyed a position of power and privilege. I attended council meetings with sorcerers from the Moon Guard, priestesses from the Sisterhood of Elune, and other influential figures. I also crossed paths with lesser-known resistance members-elves like Illidan.",
},
{
["Page"] = 2,
["Text"] = "Illidan came to Black Rook Hold with his brother, the druid Malfurion Stormrage, and the priestess Tyrande Whisperwind. I met the trio only briefly, and they did not leave any lasting impressions on me. Illidan in particular seemed like just one more sorcerer among the hundreds who had joined the resistance.\r\n\r\nYet soon, everyone would know his name. And some, like me, would come to distrust him.",
},
},
},
["Title"] = {
["enUS"] = "Worn-Edged Page",
},
["Source"] = {
["ID"] = 252386,
["Type"] = "GameObject",
},
},
["GameObject-369228"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "ARCHIVIST ROH-LUDA, RELIC RESTORER\r\n\r\nThe afterlives of the Shadowlands give rise to many curious, fantastic, and unstable relics. It is our Purpose to catalog, curate, study, and safeguard them.\r\n\r\nBy our ministrations, we will better understand the nature of each afterlife, we will comprehend how disparate souls fit in the fabric of existence, and perhaps most importantly, we will keep potentially dangerous relics out of the hands of those who would misuse them.",
},
},
},
["Title"] = {
["enUS"] = "Archivist Roh-Luda's Teachings",
},
["Source"] = {
["ID"] = 369228,
["Type"] = "GameObject",
},
},
["Item-191034"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "King Greymane,\r\n\r\nThe ally you sent to aid us was most effective, and in return for your patience, I offer welcome news.\r\n\r\nWith the formation of the new Desolate Council, one of the first topics I propose is the withdrawal of Forsaken troops from the kingdom of Gilneas. In time I hope that we may come closer to agreement, and see both lands into a brighter future.\r\n\r\nWarm Regards,\r\n\r\nCalia Menethil\r\n<The Pallid Lady>",
},
},
},
["Title"] = {
["enUS"] = "Letter to Greymane",
},
["Source"] = {
["ID"] = 191034,
["Type"] = "Item",
},
},
["GameObject-252387"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "I should have admired Illidan from the beginning. After all, he saved my father's life.\r\n\r\nIt happened during a mission that Kur'talos took into the wilds beyond Black Rook Hold. I was not there to witness it, but it was reported that one of the Legion's ravenous felhunter demons attacked and disarmed my father. The beast would have devoured him if Illidan had not intervened. With his quick thinking and mastery of the arcane, the Stormrage twin defeated the demon and spared my father a grim end.\r\n\r\nRather than downplay this event, my father celebrated it. He named Illidan his personal sorcerer, and young Stormrage became the talk of the resistance. Moon Guard members clamored for an audience with him to discuss his thoughts on the war, the nature of demons, and the arcane arts. Before long, Illidan had gained a reputation as a sorcerer without equal.",
},
{
["Page"] = 2,
["Text"] = "From that day forward, Illidan fought by my father's side in battle. I watched him like a storm crow, determined to learn more about this strange new member of my family's inner circle. \r\n\r\nWhat I discovered did not put my heart at ease. Far from it.",
},
},
},
["Title"] = {
["enUS"] = "Dog-Eared Page",
},
["Source"] = {
["ID"] = 252387,
["Type"] = "GameObject",
},
},
["Item-140262"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "FOR SALE: EZ-123 BUNKER BUILDER\r\n\r\nThe end is approaching, but you and your loved ones can survive with your very own B.B.! The Bunker Builder is the latest in gnomish engineering. Simple to operate, small enough for a mountain ram to carry, the B.B. can deploy in almost any terrain (see disclaimers). With the press of a button, the device will tunnel deep underground and hollow out a cozy cavern where you can live in peace. Each purchase comes with two air fresheners, a rope ladder (see disclaimers), and an operator's manual.\r\n\r\nDisclaimers: Not for use in sand, water, or Dalaran. Deploy rope ladder BEFORE entering the B.B. tunnel.",
},
},
},
["Title"] = {
["enUS"] = "Tattered Pamphlet",
},
["Source"] = {
["ID"] = 140262,
["Type"] = "Item",
},
},
},
