["Find me, champions, and I will grant you sight!"] = true,
["A formidable enemy is close. Strike it down with all the malice it deserves!"] = true,
["So close now to the end..."] = true,
["That's two demons down, but countless more await the attention of your blade."] = true,
["Beyond these blast doors lies the heart of the Legion's war machine. Eliminating this threat will cripple the demons' arsenal."] = true,
["Sargeras has left us a few of his favorite pets to play with. Remove these abominations from the battlefield."] = true,
