[98196] = {
["BroadcastText"] = {
["enUS"] = {
["Make your way there at once and meet with my servant, the mighty Vethir. Together, you will show the Legion how we greet their kind in Stormheim!"] = true,
["This place will test your mettle and, if you are found worthy, the Aegis of Aggramar will be yours!"] = true,
["Remain vigilant, champion! We must watch for our enemy, just as they are watching us!"] = true,
["The Legion tricked us! Their attacks were merely a diversion while they established a foothold upon the isle of Shield's Rest!"] = true,
["Before you lies your next trial. Defeat both Hyrja and Fenryr and you will have proven your worth to me!"] = true,
["Long have I awaited noble champions to enter my realm. Behold! The Halls of Valor!"] = true,
["The Legion dispatches its all-seeing eyes to spy on our war efforts. Intolerable! Ensure nothing they have learned can be used against us."] = true,
["Well done, hero! You have saved many noble souls from becoming fuel for the Legion's foul magic."] = true,
["To the victor go the spoils... The Aegis of Aggramar is yours for the taking."] = true,
["Throughout your trials, you have demonstrated strength, skill, and intellect-traits shared by the greatest of our vrykul kings. Now... you will face them in combat. Emerge victorious, and you may yet claim your prize!"] = true,
["You have earned my blessing, champions! I look forward to meeting you within the Hall of Glory!"] = true,
["The Legion defiles the shores of Stormheim! Do not allow a single demon to remain!"] = true,
["Only by strength in battle can you be measured a champion. Let my stormforged begin your test!"] = true,
["The mighty Fenryr stalks these grounds. It will take cunning and guile to slay this beast - a perfect test of your worthiness."] = true,
},
},
