[178069] = {
["BroadcastText"] = {
["enUS"] = {
["Ah, it worked! As I knew it would, of course."] = true,
["In exchange, I will inform you if I discover any commentary on your dialogues with Ve'rayn among her records."] = true,
["Interesting! I've made an adjustment to the device to modify the destination coordinates."] = true,
["Rule 5: Be audacious, when the situation demands it. The Mawsworn rarely expect this."] = true,
["You were transferred, yes?"] = true,
["A very profitable effort, indeed."] = true,
["You have done me a great favor. Ve'rayn had proven herself... problematic for some time."] = true,
["To the River of Souls you must go. Gorgoa flows through the Maw, delivering damned souls to their fate."] = true,
["Hurry along now. We have much to discuss."] = true,
["Oh dear, I seem to have left my bag in that musty cave. Retrieve it for me and we shall depart."] = true,
["I must ask you to brave its perils and bring me remnants of the spirits that linger there."] = true,
["Better, but still distorted. Try another placement at a lower elevation."] = true,
["This is no time for idle chatter, Maw Walker. Come, we have much to do."] = true,
["Cartel Ve will continue to send operatives after me, but eliminating Ve'rayn affords me significant time."] = true,
["Although I am certain there's nothing to be concerned about there..."] = true,
["Interesting! Are those glittering objects... feathers?"] = true,
["There you are! I trust my bag isn't too heavy for you. Come along, then. We have much to do."] = true,
["Ah! I am receiving. The signal is very poor. Find a new location to relay."] = true,
["What an admirably specific question... the answer to which I can only hypothesize."] = true,
},
