[118781] = {
["BroadcastText"] = {
["enUS"] = {
["Champions must show cleverness as well as might!"] = true,
["Champions! You have spilled the blood of Helya's minions. The time has come to enter Helheim itself and end the sea witch's dark reign. But first... a final challenge!"] = true,
["Well fought! Now, onward to Helya! This day her treachery shall be ended!"] = true,
["The battle is yours to begin, heroes!"] = true,
["Well done, hero! You have saved many noble souls from becoming fuel for the Legion's foul magic."] = true,
["Well done... so far! But I will judge for myself whether you are worthy!"] = true,
["My ancient nemesis has been vanquished! The curse that bound me to the Halls of Valor is broken at last."] = true,
["The Legion defiles the shores of Stormheim! Do not allow a single demon to remain!"] = true,
["That vile demon is moving his vessel to attack the Gates of Valor! I've sent one of my val'kyr to aid you, hero. This battle must be won!"] = true,
["Make your way there at once and meet with my servant, the mighty Vethir. Together, you will show the Legion how we greet their kind in Stormheim!"] = true,
["Feel the fury of the storm!"] = true,
["Revel in the spoils of victory, worthy champions! The day will come when I have need of your courage and skill once more."] = true,
["Hold nothing back! I must know they are ready for the task ahead."] = true,
["The Legion tricked us! Their attacks were merely a diversion while they established a foothold upon the isle of Shield's Rest!"] = true,
["Hear now the tale of how Skovold stole his title of king. Witness the treachery he showed the one who bore him."] = true,
["Well done! Our world will never fall so long as it is defended by champions such as you!"] = true,
["Spirits of the fallen cry out as Legion hounds drain their life essence. Free the spirits from their torment and purge the Legion filth!"] = true,
["The Halls of Valor echo with the songs of those you rescued. Magnificently done!"] = true,
["It seems I have been too gentle. Have at thee!"] = true,
["ENOUGH! Your worth is proven! With you as my champions, Helya will fall and I will at long last be free of the curse that binds me here."] = true,
["Beware, champions! Helya's realm is guarded by a savage beast bred from the stuff of nightmares!"] = true,
["Hmm... Many ages have passed since my eyes looked upon the halls of Ulduar. Perhaps I should visit my watcher kin... we have much to speak of. Farewell!"] = true,
["Champion, a great malevolence has risen in the mists. Gather your most powerful allies and meet the kvaldir in battle!"] = true,
["The Legion corrupts everything it touches! Destroy their fel corruptors before all of Stormheim is tainted!"] = true,
["Hymdall! Hyrja! Test the mettle of these mortals. I must be certain they possess the courage and skill needed for what is to come."] = true,
},
},
["Name"] = {
["enUS"] = "Odyn",
},
},
