[122366] = {
["BroadcastText"] = {
["enUS"] = {
["Death... claims... us all."] = true,
["Come, then. We will trade pain for pain!"] = true,
["Draw your blades! I will show you torment!"] = true,
["When your thrones run red with betrayal... when your holy places burn and the shattered mask hangs above your hearth... only then you will know. And it will be too late."] = true,
["It matters not. You are blind to the true darkness closing in around you."] = true,
["So, she found me at last. Sent her underlings to finish the job."] = true,
["Is that all you can take?"] = true,
["Tell me, when she seized your throne of hides and bones, was your allegiance forced? No... I'd wager you surrendered it willingly... or were convinced you did."] = true,
["Your torment... is only... beginning."] = true,
["It matters not. You are blind to the darkness in your midst."] = true,
["So, your Alliance still endures. Longer than I expected, though she has already planted the seeds of its downfall. She is patient, that one."] = true,
["Grah! Damnable witches!"] = true,
["Aaaarggh! Witches! You call that torment? I have endured far worse!"] = true,
},
