[115366] = {
["BroadcastText"] = {
["enUS"] = {
["The Legion landed right on our doorstep - and Elisande simply let them in. Disgusting. Strike at Felsoul Hold! Show the Legion that some of us are not so easily broken!"] = true,
["If we can control the Nightspire, the palace will fall. Stop the ritual!"] = true,
["We must bolster our ranks. Seek out the withered and soothe their rage. I will beckon them to Shal'Aran."] = true,
["What madman thought to infuse this creature with the Nightwell's power? Have a care. If this abomination was created to protect lower reaches of the citadel from invaders, it must be particularly deadly."] = true,
["In order to free our allies at the gate, this monstrosity must be destroyed!"] = true,
["Find the palace's supply route and cut it off. Flightmaster Volnath should be near the captain's quarters."] = true,
["At long last, the battle to liberate Suramar is joined! No more must our resistance hide in the shadows!"] = true,
["The time lock is broken! They are free!"] = true,
["Victory over Elisande will require strength beyond our own. Ascend to the Lunar Crucible and seek the blessing of the Moon Guard ancients."] = true,
["Without a steady stream of supplies, the palace will soon fall! Well done."] = true,
["We are one step closer to ending this madness. Elisande's final hour has come!"] = true,
["What can I say? He took his job seriously."] = true,
["The people of Suramar owe these heroes a debt we can never fully repay. I will stand with them until the end."] = true,
["Etraeus thought himself superior to... well, everyone. I confess I enjoyed seeing him humbled."] = true,
["The fal'dorei have breached the palace! Stop them before the guards take notice!"] = true,
["I don't believe our cover has been compromised. Quickly, find Aluriel and breach the gates!"] = true,
["Tendrils of power are emanating from the aberration. I believe Elisande is using this creature to maintain the time lock spell."] = true,
["The palace grounds are just ahead. You'll find them even more heavily defended than the lower levels."] = true,
["Now the fate of my people rests in the hands of outsiders... all of you... to save us from the terrible bargain made by our queen."] = true,
["Shanar daloras! I have no idea how such an entity came to be, but the essence of the Nightwell is surging through it."] = true,
["This is a momentous day, my friends. Until the Legion came, no outsider was permitted inside the corridors of the Nighthold for ten-thousand years."] = true,
},
},
["Name"] = {
["enUS"] = "First Arcanist Thalyssra",
},
},
[99496] = {
["Name"] = {
["enUS"] = "Never Ending Treasure",
},
},
[254266] = {
["BroadcastText"] = {
["enUS"] = {
["I'll carve out those pieces like I was holding a scalpel."] = true,
},
},
["Name"] = {
["enUS"] = "Leona Darkstrider",
},
},
[122022] = {
["Name"] = {
["enUS"] = "Umbralfin",
},
},
[115367] = {
["BroadcastText"] = {
["enUS"] = {
["That was for Tirion Fordring, monster! Krosus may not have struck the killing blow, but he played a part in our great champion's fall."] = true,
["If the Legion is using that hub to gather reinforcements, then it must be destroyed before we are overwhelmed."] = true,
["We can stop him! I know it!"] = true,
["Agreed. We must cripple those infernal engines of destruction. Champions, use this teleporter to board the Vindicaar. On to our next target!"] = true,
["In the Third War, Tichondrius fell in battle against Illidan Stormrage. I think the demon hunter's spirit is pleased that the dreadlord has met another painful end."] = true,
["No doubt our forces will be disoriented. I will inform them what happened and see that they make ready to resume our assault."] = true,
["I'll keep an eye on your progress. Good luck!"] = true,
["Without their portals, the Legion is cut off from reinforcements. Now is the time to press our attack!"] = true,
["So the palace gardener turned himself into a plant?"] = true,
["I'll see to fortifying our position here. Thalyssra, your guidance has been invaluable to our champions so far. They'll rely upon your wisdom in the battles ahead."] = true,
["The gates are breached! Sorry we couldn't join you sooner, but we had a bit of a mess to clean up out front."] = true,
},
},
["Name"] = {
["enUS"] = "Archmage Khadgar",
