[118440] = {
["BroadcastText"] = {
["enUS"] = {
["Malfurion! No, it cannot be! I prayed my thero'shan would never fall to the Nightmare. Yet here you stand, casting a shadow upon the purity of the Dream!"] = true,
["Is that you, Thero'shan?"] = true,
["The impurity must be cleansed!"] = true,
["Your triumph restores the Dream and safeguards your world. The allies of Xavius will never relent, but this road, at least, is closed to them."] = true,
["Father! I have... failed you..."] = true,
["Heroes! Champions! Step forth and hear me!"] = true,
["The Nightmare has long been a cancer eager to consume the Emerald Dream. Had Xavius succeeded, his corruption would have overwhelmed Azeroth, giving rise to a living Nightmare."] = true,
["Thero'shan... how... could you?"] = true,
["The Burning Legion is a plague that sickens the land with its presence. The demons must be purged before their forces spread any further!"] = true,
["You fight with noble hearts! Could it be true? Could the darkness be inside of... me?"] = true,
