[246154] = {
["BroadcastText"] = {
["enUS"] = {
["Aren't you tired of fighting? What if I could show you a better way?"] = true,
["You have a glorious destiny. All you need to do is join us!"] = true,
["I'll bring your end here and now!"] = true,
