},
[125683] = {
["BroadcastText"] = {
["enUS"] = {
["If the Legion harnesses the power of this realm, they will be unstoppable. Drive them out."] = true,
["Few understood my use of the naga to obtain the Eye of Sargeras, but it was a necessary tactic to secure the future of Azeroth. Let nothing stop you from doing what needs to be done!"] = true,
["This world holds a power that the Legion must not possess. Prevent them from claiming it."] = true,
["I sense a nearby target. Strike swiftly!"] = true,
["The demons have spliced spores into their own flesh to mask their attacks. Show them they cannot hide from death!"] = true,
["That's two demons down, but countless more await the attention of your blade."] = true,
["Sargeras has left us a few of his favorite pets to play with. Remove these abominations from the battlefield."] = true,
["An impressive victory. Your resolve remains unwavering."] = true,
["Bold words, Khadgar, but victory requires more than courage alone. The armies of your Alliance and Horde had courage... before facing slaughter on the Broken Shore. The Deceiver will turn your fears and doubts against you."] = true,
["The Legion is in its death throes. Time to put our boot to their throats. Return to the Vindicaar and prepare to strike the killing blow."] = true,
["This agent of the Legion underestimates your might. Make plain the error of its ways."] = true,
["Now is your chance. Finish this fight!"] = true,
["So close now to the end..."] = true,
["Should they fall to darkness, Sargeras will have the power he needs to claim the final titan."] = true,
["The Legion is reeling from your onslaught. Cut them down!"] = true,
["The heart of Antorus lies before us. The power behind the Legion's infinite army."] = true,
["The Legion drains the blood of a colossal creature that slumbers beneath the surface. They must be stopped!"] = true,
["The Legion has unleashed another of its pawns. Dispose of this threat at once."] = true,
["Be on your guard. I doubt the spirits trapped here will be friendly... or forgiving."] = true,
["You've driven them back! Now press the attack!"] = true,
["Another champion of the Legion is near. End its existence."] = true,
["A threat closes in. Bring it down, and show the demons they cannot stand against us."] = true,
["This frozen world holds dangerous power. Ensure the Legion cannot claim it."] = true,
["Who could ever imagine such a sacrifice?"] = true,
["An age has passed since I last walked these halls. I did what needed to be done, though at great cost."] = true,
["That fiend earned its death a thousand times over. Now it shall suffer the wrath of its vile master."] = true,
["No matter how many monstrosities they send at us, we will cut them down."] = true,
["This way! Come at once!"] = true,
["Well done, champions. News of this victory will spread throughout the Dark Beyond."] = true,
["These fools should've run when they had the chance. Leave none standing."] = true,
["Eredar sorcerers twist the fel blood of this world into weapons to use against us. They must be dismantled."] = true,
["The Legion's thirst for blood is unquenchable. Remove their filth from this world."] = true,
["Ah yes, the unmistakable stench of Legion filth. Seek out the source and destroy it!"] = true,
["Beyond these blast doors lies the heart of the Legion's war machine. Eliminating this threat will cripple the demons' arsenal."] = true,
["The echo of the Guardian Aegwynn appears, just as she did in the cathedral."] = true,
["Leave none standing! If we fail here, Azeroth burns."] = true,
},
},
["Name"] = {
["enUS"] = "Illidan Stormrage",
},
