[125691] = {
["BroadcastText"] = {
["enUS"] = {
["I think it wise to divide our efforts. I'll work to circumvent the tower's magical defenses. You may need to take a more... blunt force approach."] = true,
["I have a very sticky situation for you, champion. We need silk harvested from the broods of the Creeping Grotto to use for a rather complex incantation. Can you help?"] = true,
["That was for Tirion Fordring, monster! Krosus may not have struck the killing blow, but he played a part in our great champion's fall."] = true,
["If the Legion is using that hub to gather reinforcements, then it must be destroyed before we are overwhelmed."] = true,
["The presence of the Tidestone has drawn out the fanatical followers of Queen Azshara, including the elusive Warlord Darjah. An excellent opportunity to remove this threat."] = true,
["In the Third War, Tichondrius fell in battle against Illidan Stormrage. I think the demon hunter's spirit is pleased that the dreadlord has met another painful end."] = true,
["Well done, heroes. The loss of Warlord Darjah weakens the naga's might within the tomb."] = true,
["Without their portals, the Legion is cut off from reinforcements. Now is the time to press our attack!"] = true,
["I'll see to fortifying our position here. Thalyssra, your guidance has been invaluable to our champions so far. They'll rely upon your wisdom in the battles ahead."] = true,
["Heroes, the paths are open. Use the Pillars of Creation to bypass Aegwynn's wards before the Legion claims the avatar."] = true,
["The Legion's presence has stirred an ancient hydra known as Deepmaw. Destroy this creature before its wrath is unleashed upon our world."] = true,
["We will put a stop to Kil'jaeden's plan, Aegwynn. This time we will not fail."] = true,
["Time to return the demon hunter's soul to his body... and deny the Legion's master a host!"] = true,
["Champions, there is a disturbance close to your location the likes of which I haven't felt since the opening of the Dark Portal."] = true,
["Quickly, bolster our ranks! We must push through!"] = true,
["Then we have no time to lose."] = true,
["Fall back!"] = true,
["I'll keep an eye on your progress. Good luck!"] = true,
["The gates are breached! Sorry we couldn't join you sooner, but we had a bit of a mess to clean up out front."] = true,
["So the palace gardener turned himself into a plant?"] = true,
["You're right, Illidan. Kil'jaeden and the Legion have defeated each of us in the past. But if we stand together, Azeroth can yet be saved. I know it!"] = true,
["Champion, mages of the Tirisgarde need your help to purge the spider broods from the Creeping Grotto. Their pyromancers could provide you with a burning edge."] = true,
},
},
["Name"] = {
["enUS"] = "Archmage Khadgar",
},
