["Well done, champions. For the first time in millennia, a blow has been struck against the denizens of the Burning Throne."] = true,
["Argus! My beloved homeworld... what have they done to you?"] = true,
["Rendezvous with the Vindicaar so we can prepare for the final attack."] = true,
["Remain here, Magni. The rest of us will go on."] = true,
["I recognize the trappings of the generals commanding the Legion's forces. Before Sargeras took our world, these generals martialed our armies and brought peace to Argus."] = true,
["They betrayed everything we stood for when they accepted his bargain. There can be no redemption... only retribution."] = true,
