[123689] = {
["BroadcastText"] = {
["enUS"] = {
["Do you think me a fool? Fiends, to me!"] = true,
["I will be reborn by Argus' flame! I will never... stop... fighting."] = true,
["Talestra the Vile begins phasing into this timeline..."] = true,
