[162804] = {
["BroadcastText"] = {
["enUS"] = {
["That Xy Cartel has lost control of the docks. I need someone competent to sort it out for them."] = true,
["My fellow brokers whisper legends of this place. A magnificent city filled with treasures, its location a closely guarded secret."] = true,
["Be on alert. No doubt the Jailer's Eye will be upon this place."] = true,
["Ah, Maw Walker. I was wondering when you would show up."] = true,
["I have the means to keep us hidden, as I have before."] = true,
["Stay close and obey my every word, lest the Jailer's Eye reduce you to stygia."] = true,
["Reports I intercepted from the Mawsworn indicate that the Jailer has been seeking a realm called Korthia."] = true,
["The Jailer has used enormous chains to pull a broken realm into the Maw. I caught only a glimpse, but I have a suspicion of what it might be."] = true,
["I suggest we travel there together. While you search for your waystone, I will determine what potential profits lie in store. For both of us, I mean."] = true,
["I possess a device that will take us to a safe enclave near this landmass. Once we arrive, it is imperative that you stay close."] = true,
