["We are ready to begin the offensive in Suramar. Place beacons along the city's outskirts and draw the withered down upon the Magistrix's forces!"] = true,
["What madman thought to infuse this creature with the Nightwell's power? Have a care. If this abomination was created to protect lower reaches of the citadel from invaders, it must be particularly deadly."] = true,
["Let this be a lesson to those who flaunt their power."] = true,
["Elisande's personal construct is nearby. It would be a shame if something bad happened to it..."] = true,
["Etraeus thought himself superior to... well, everyone. I confess I enjoyed seeing him humbled."] = true,
["The people of Suramar owe these heroes a debt we can never fully repay. I will stand with them until the end."] = true,
["What can I say? He took his job seriously."] = true,
["At long last, the battle to liberate Suramar is joined! No more must our resistance hide in the shadows!"] = true,
["Tendrils of power are emanating from the aberration. I believe Elisande is using this creature to maintain the time lock spell."] = true,
["The palace grounds are just ahead. You'll find them even more heavily defended than the lower levels."] = true,
["Now the fate of my people rests in the hands of outsiders... all of you... to save us from the terrible bargain made by our queen."] = true,
["Shanar daloras! I have no idea how such an entity came to be, but the essence of the Nightwell is surging through it."] = true,
["This is a momentous day, my friends. Until the Legion came, no outsider was permitted inside the corridors of the Nighthold for ten-thousand years."] = true,
},
},
