[117269] = {
["BroadcastText"] = {
["enUS"] = {
["Fall, hero!"] = true,
["Damnable mortals! You scurry through this tomb like vermin, dispatching my underlings and imagining yourselves the equals of the Legion. Heroes... champions... fools!"] = true,
["Still... I will not deprive you of this chance to fall before an ancient wonder. Let this avatar be the end of you!"] = true,
["Death rains upon you!"] = true,
["What is this? Even when your own doubts and fears are made manifest, you will not yield?"] = true,
["Insolent mortals! Your fate was sealed the moment you stepped into the Nether!"] = true,
["The husk before you was once a vessel for the might of Sargeras. But this temple itself is our prize. The means by which we will reduce your world to cinders!"] = true,
["This battle shall be your last!"] = true,
["Fall into darkness!"] = true,
["You cannot resist your own nature."] = true,
["Give in to your fears! Your desires!"] = true,
["You were fools to follow me here!"] = true,
["An inevitable fate!"] = true,
["Is there no end to your sanctimonious bluster, Velen? You claim the mantle of prophet, yet you always lacked the vision to see the inevitable destiny of our world... of all worlds."] = true,
["Somehow you survived! No matter. Look upon our wonders, you mortals, and despair! Behold the world that shall be your tomb!"] = true,
["Fall before your master!"] = true,
["Face your destiny!"] = true,
["Who will share your fate?"] = true,
["Consume them all!"] = true,
["Still you resist! Then let me repay your arrogance!"] = true,
["Obliteration beckons!"] = true,
["You will all burn!"] = true,
["It is a simple matter to show courage against my minions. Can you face the shadows within your own souls as bravely?"] = true,
["Who will save you now?"] = true,
["A vessel for my fury!"] = true,
["Still you fight us! Still you deny the inevitable! Your incessant resistance is maddening! Why will you not yield?"] = true,
["A meaningless struggle! Azeroth shall fall to the Burning Legion!"] = true,
},
},
["Name"] = {
["enUS"] = "Kil'jaeden",
},
