[237504] = {
["BroadcastText"] = {
["enUS"] = {
["Enough! Like everything else you do, this plan to infiltrate the cult is foolhardy and dangerous. It had better work, Umbric."] = true,
["Yet more minds twisted by the Void. This must seem quite familiar to you, Umbric."] = true,
["Infiltrate the cult and see what you can learn. But do not succumb to the allure of their sermons."] = true,
["Meet me in Orgrimmar so we may root out this evil. We cannot suffer a single cultist within our walls."] = true,
["$PLAYER_NAME$, I have heard unsettling rumors that Xal'atath's Twilight's Blade cult is recruiting within Horde cities."] = true,
["I will not be lectured by you! Not when you forced me to exile you from Silvermoon for refusing to abandon your forbidden research!"] = true,
["Every practitioner of void magic is a threat, Umbric. Have your own mistakes and misadventures done nothing to teach you that?"] = true,
["Over here, $PLAYER_NAME$. I've tracked the cultists' activity to the caves below."] = true,
["I maintain that this plan was a risk, Umbric. Luck has once again spared us from your recklessness."] = true,
["We may have removed the cult's presence from Orgrimmar and Stormwind, but their numbers still grow. This is a staging ground."] = true,
