[102282] = {
["BroadcastText"] = {
["enUS"] = {
["The San'layn are cold and arrogant creatures. They inflict pain for pure entertainment. All in all, they sound like my kind of people."] = true,
["I sense great fury and bitterness in this gnome. She has kept these feelings bottled up for so long... It is only a matter of time before she explodes."] = true,
["You will fall... sooner or later..."] = true,
["I expected more from these prisoners. If they cannot break you, then I will."] = true,
["Crypt lords do not take defeat well. Being locked in this prison will have made this one angry... Very, VERY angry."] = true,
["The fall of Dalaran begins here. These prisoners will stain the streets red with blood. And when they're done, the Legion will bring this city crashing to the ground!"] = true,
["Pity... I will not see the world... burn..."] = true,
["Come now, Anub'esset! You call yourself a great crypt lord, and you can't even burrow your way out of this prison? Show us why you are to be feared!"] = true,
["Ah... even I have heard of Shivermaw, the fallen blue dragon once known as Eldragosa. She will be perfect for terrorizing the skies of Dalaran."] = true,
},
},
["Name"] = {
["enUS"] = "Lord Malgath",
},
},
[104636] = {
["BroadcastText"] = {
["enUS"] = {
["Nature will rise against you!"] = true,
["Allies! To my side!"] = true,
["We must strike before their defenses reach full power! Plant a Seed of Ruin near each structure and it will be crushed as the seed sprouts. Hurry!"] = true,
["It pains me to see this ancient land tainted by such pestilent creatures. Stop them before they spread!"] = true,
["Your death fortifies the Dream!"] = true,
["To honor your courage, I offer passage into the pure heart of the Dream. As you feel the essence of life blooming beneath your feet, know that it endures thanks to what you achieved this day."] = true,
["Liars! Servants of darkness! It will give me no pleasure to destroy you, but my duty is to the Dream. Andu-falah-dor!"] = true,
["Your triumph restores the Dream and safeguards your world. The allies of Xavius will never relent, but this road, at least, is closed to them."] = true,
["The Legion is a relentless foe, but you have saved the forest this day. All of Val'sharah honors your victory!"] = true,
["Well done, hero! Our druids will see to the rest of this menace."] = true,
["Thero'shan... how... could you?"] = true,
["The Nightmare has long been a cancer eager to consume the Emerald Dream. Had Xavius succeeded, his corruption would have overwhelmed Azeroth, giving rise to a living Nightmare."] = true,
["Filth! Defiler!"] = true,
["Come forth and fight for the Dream!"] = true,
["There! Stop the demon before it calls forth more of its vile kind!"] = true,
["Father! I have... failed you..."] = true,
["Sacred vines, entangle the corrupted!"] = true,
["The impurity must be cleansed!"] = true,
["The death of those foul creatures will stoke the fire of the Legion's wrath. Make haste to Black Rook Hold. We must press our attack!"] = true,
["Attack the corruptors!"] = true,
["Heroes! Champions! Step forth and hear me!"] = true,
["Is that you, Thero'shan?"] = true,
["Malfurion! No, it cannot be! I prayed my thero'shan would never fall to the Nightmare. Yet here you stand, casting a shadow upon the purity of the Dream!"] = true,
["Father? Father, is that you?"] = true,
["What wickedness is this, Malfurion?"] = true,
["Yes, father! I will not fail you!"] = true,
["The demons have taken the lands above Moonclaw Vale! The trees cry out as their life essence is drained to fuel the Legion's defenses."] = true,
["The Burning Legion is a plague that sickens the land with its presence. The demons must be purged before their forces spread any further!"] = true,
["You fight with noble hearts! Could it be true? Could the darkness be inside of... me?"] = true,
},
},
